"""Publish a source-dated DigitalOcean guide without changing existing price records or shared policy."""
from pathlib import Path
from html import escape
from string import Template
import json

from config import ROOT


def publish_digitalocean_article(output, cfg):
    route = '/pricing/digitalocean/'
    observation = OBSERVATION
    checked = max(source['checked_at'] for source in observation['sources'])
    assert all(source['status'] == 200 and source['robots_allowed'] for source in observation['sources'])
    body = BODY
    title = 'DigitalOcean pricing: monthly caps and retained resource costs | ' + cfg['brand']
    description = 'Seven Basic Regular plans, with source-linked annual budgets, transfer and storage calculations, and charges after shutdown or deletion.'
    url = cfg['base_url'] + route
    schema = json.dumps({'@context': 'https://schema.org', '@graph': [{
        '@type': 'Article', 'headline': 'DigitalOcean pricing', 'url': url,
        'dateModified': checked, 'inLanguage': 'en-US',
        'publisher': {'@type': 'Organization', 'name': cfg['brand']},
    }]})
    document = Template((ROOT/'templates/base.html').read_text(encoding='utf-8')).substitute(
        title=escape(title), description=escape(description), brand=escape(cfg['brand']),
        canonical='<link rel="canonical" href="'+escape(url)+'">' if cfg['base_url'] else '<meta name="robots" content="noindex">',
        schema=schema, url=escape(url), image=escape(cfg['base_url']+'/assets/og.png'),
        asset_version='guide', body=body, repository=escape(cfg['repository_url']))
    target = Path(output)/route.strip('/')/'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(document, encoding='utf-8')
    hub = Path(output)/'providers/digitalocean/index.html'
    if hub.exists():
        original = hub.read_text(encoding='utf-8')
        link = '<section class="prose"><h2>Read the DigitalOcean pricing guide</h2><p><a href="/pricing/digitalocean/">Check annual budgets, transfer and storage charges, and costs after shutdown or deletion.</a></p></section>'
        hub.write_text(original.replace('</main>', link+'</main>', 1), encoding='utf-8')
    return route, checked


OBSERVATION = {'sources': [{'name': 'do-pricing', 'url': 'https://www.digitalocean.com/pricing/droplets', 'robots_allowed': True, 'status': 200, 'final_url': 'https://www.digitalocean.com/pricing/droplets', 'checked_at': '2026-11-13T02:10:12+00:00', 'sha256': 'dbb8bb544c1deff5cd78fd4f2c307e278ac20393302907e234b1dd10adfe3cda', 'bytes': 481380}, {'name': 'do-billing', 'url': 'https://docs.digitalocean.com/products/droplets/details/pricing/', 'robots_allowed': True, 'status': 200, 'final_url': 'https://docs.digitalocean.com/products/droplets/details/pricing/', 'checked_at': '2026-11-13T02:10:11+00:00', 'sha256': 'c6be6501ef3e9c004dec9df0a67f395a8558bbeb446841cb0495f168173135b3', 'bytes': 60944}, {'name': 'do-transfer', 'url': 'https://docs.digitalocean.com/platform/billing/bandwidth/', 'robots_allowed': True, 'status': 200, 'final_url': 'https://docs.digitalocean.com/platform/billing/bandwidth/', 'checked_at': '2026-11-13T02:10:11+00:00', 'sha256': '257aa56ca09a4538f26b1f0b43fb342c3ce07069af5a097fbc80ee7ef041f7d3', 'bytes': 49742}, {'name': 'do-volumes', 'url': 'https://docs.digitalocean.com/products/volumes/details/pricing/', 'robots_allowed': True, 'status': 200, 'final_url': 'https://docs.digitalocean.com/products/volumes/details/pricing/', 'checked_at': '2026-11-13T02:10:11+00:00', 'sha256': 'e9f19d2443d46b686544f2a67545bb8007b023fc5a8dd36baaa63ebde8421d8d', 'bytes': 35504}, {'name': 'do-snapshots', 'url': 'https://docs.digitalocean.com/products/snapshots/details/pricing/', 'robots_allowed': True, 'status': 200, 'final_url': 'https://docs.digitalocean.com/products/snapshots/details/pricing/', 'checked_at': '2026-11-13T02:10:12+00:00', 'sha256': '560dd2778499dee592a32d7a39c24d5b5b337ef862a5c4afc29dd94a7308a7c1', 'bytes': 34965}, {'name': 'do-destroy', 'url': 'https://docs.digitalocean.com/products/droplets/how-to/destroy/', 'robots_allowed': True, 'status': 200, 'final_url': 'https://docs.digitalocean.com/products/droplets/how-to/destroy/', 'checked_at': '2026-11-13T02:10:12+00:00', 'sha256': 'cc29dbb6e0ca7774bff43b2ed9e7d69c7d6ed55a3b1f2e0cc15de1fe759aad58', 'bytes': 62320}]}

BODY = '<h1>DigitalOcean pricing</h1>\n<p>DigitalOcean Basic Regular Droplets cost <strong>$4–$96 per month</strong> across the seven sizes checked below. The 1 GiB plan is $6 per month, or $72 for twelve full billed months in our unchanged-rate scenario. Outbound transfer beyond the team allowance costs $0.01/GiB; Standard block storage is $0.10/GiB-month. Switching a Droplet off does not stop its bill. These are USD list rates before tax, not a prepaid annual offer. <a href="#sources">Official evidence and check date</a>.</p>\n<h2>Basic Regular plans: the price you are comparing</h2>\n<p>This table covers the Regular CPU option under Basic Droplets. Premium CPUs, v5 configurations and GPU plans are outside its scope. Monthly figures are published bundled-plan caps; hourly figures are the displayed rates, not prices calculated by dividing the cap.</p>\n<div class="table-wrap" tabindex="0" role="region" aria-label="Basic Regular prices, scroll horizontally"><table><thead><tr><th scope="col">Memory</th><th scope="col">vCPU</th><th scope="col">SSD</th><th scope="col">Included transfer</th><th scope="col">USD/hour</th><th scope="col">USD/month cap</th></tr></thead><tbody><tr><th scope="row">512 MiB</th><td>1 vCPU</td><td>10 GiB</td><td>500 GiB</td><td>$0.00595</td><td>$4.00</td></tr><tr><th scope="row">1 GiB</th><td>1 vCPU</td><td>25 GiB</td><td>1,000 GiB</td><td>$0.00893</td><td>$6.00</td></tr><tr><th scope="row">2 GiB</th><td>1 vCPU</td><td>50 GiB</td><td>2,000 GiB</td><td>$0.01786</td><td>$12.00</td></tr><tr><th scope="row">2 GiB</th><td>2 vCPUs</td><td>60 GiB</td><td>3,000 GiB</td><td>$0.02679</td><td>$18.00</td></tr><tr><th scope="row">4 GiB</th><td>2 vCPUs</td><td>80 GiB</td><td>4,000 GiB</td><td>$0.03571</td><td>$24.00</td></tr><tr><th scope="row">8 GiB</th><td>4 vCPUs</td><td>160 GiB</td><td>5,000 GiB</td><td>$0.07143</td><td>$48.00</td></tr><tr><th scope="row">16 GiB</th><td>8 vCPUs</td><td>320 GiB</td><td>6,000 GiB</td><td>$0.14286</td><td>$96.00</td></tr></tbody></table></div>\n<p>Data from the <a href="https://www.digitalocean.com/pricing/droplets">DigitalOcean official pricing page</a>, Basic Droplets → Regular, columns Memory, vCPU, Transfer, SSD, $/hr and $/mo. Checked <time datetime="2026-11-13T02:10:12+00:00">2026-11-13 02:10 UTC</time>. Read across one row; do not mix CPU tabs.</p>\n<h2>Backup options are separate from the compute cap</h2>\n<p>Percentage-based basic backups add 20% for weekly backups or 30% for daily backups. On a full-month $6 Droplet, our arithmetic is $6 × 20% = $1.20 extra for weekly backups, or $6 × 30% = $1.80 extra for daily backups. These are alternatives, not fees to add together. Usage-based backup plans have a different mechanism and are not estimated here. Source: <a href="https://www.digitalocean.com/pricing/droplets">Additional product pricing → Backups, weekly and daily entries</a>; checked 2026-11-13 02:10 UTC.</p>\n<h2>Year one versus year two: separate a model from a renewal quote</h2>\n<section data-authored-calculation="annual"><p>Our scenario keeps one 1 GiB Basic Regular Droplet for twelve full billed months in each year. It excludes credits, taxes, backups and retained resources, and assumes the currently observed $6 monthly cap remains unchanged. It is a budgeting model, not a promise about next year\'s rate.</p>\n<p><strong>Year one: 12 × $6 = $72. Year two: 12 × $6 = $72. Modelled difference: $72 − $72 = $0.</strong> A separately guaranteed renewal-year tariff was <strong>Not obtained</strong>. Do not label the $6 list rate a first-year promotion, or treat the $0 modelled difference as a guaranteed renewal discount.</p>\n<p>For a different future monthly rate R, the same model becomes year two = 12 × R and the increase over year one = 12 × (R − $6). R is deliberately left unknown. If checkout applies an account credit, record it separately from the recurring rate rather than reducing the base price in this table.</p>\n<p>Rate evidence: <a href="https://www.digitalocean.com/pricing/droplets">Basic Regular table, 1 GiB row, $/mo cell</a>. Billing evidence: <a href="https://docs.digitalocean.com/products/droplets/details/pricing/#bundled-cpu-droplet-billing">Bundled CPU Droplet Billing, paragraphs 1–2</a>. Quantities and unchanged-rate assumption are ours.</p></section>\n<h2>Extra transfer and storage: work out the resource subtotal</h2>\n<section data-authored-calculation="capacity"><p>For this scenario, the team\'s actual outbound usage exceeds its accrued pooled allowance by 100 GiB. Separately, one 50 GiB Standard block volume exists for the full billing month. Those quantities are assumptions; they are not included benefits or measured usage.</p>\n<p><strong>Transfer overage = 100 GiB × $0.01/GiB = $1. Standard volume = 50 GiB × $0.10/GiB-month = $5. Resource subtotal = $6 + $1 + $5 = $12.</strong> This excludes tax, backups and snapshots. Extra block storage is a separate volume; it does not increase the plan\'s RAM or CPU. There is no claim here that a boot disk can silently overflow into paid capacity.</p>\n<p>The threshold matters: use max(0, team outbound GiB − accrued team allowance GiB), not one Droplet\'s traffic minus its advertised full-month allowance. The billing documentation accrues allowance as a Droplet exists and pools it across the team. A short-lived Droplet therefore needs a prorated allowance check before this example can be reused.</p>\n<p>Evidence: <a href="https://docs.digitalocean.com/platform/billing/bandwidth/#droplets">Bandwidth Billing → Droplets, paragraphs 1–2; Details and Examples, paragraph 1</a>; <a href="https://docs.digitalocean.com/products/volumes/details/pricing/">Volume Pricing, first pricing paragraph and attachment statement</a>. A separate automatic boot-disk overage tariff was <strong>Not obtained</strong>; no such charge is assumed.</p></section>\n<h2>Off, destroyed, or fully cleaned up: follow the surviving resources</h2>\n<section data-authored-calculation="retention"><p>Hold a 1 GiB Droplet, a 50 GiB Standard volume and one 20 GB Droplet snapshot for a complete billing month. Here 20 GB is assumed billable snapshot size, not the capacity of the source disk. Keep GB and GiB as the provider labels them.</p>\n<div class="table-wrap" tabindex="0" role="region" aria-label="Retained resource scenario, scroll horizontally"><table><thead><tr><th scope="col">State for the modelled month</th><th scope="col">Droplet</th><th scope="col">Volume</th><th scope="col">Snapshot</th><th scope="col">Resource subtotal</th></tr></thead><tbody>\n<tr><th scope="row">Powered off; all resources kept</th><td>$6</td><td>50 × $0.10 = $5</td><td>20 × $0.06 = $1.20</td><td>$12.20</td></tr>\n<tr><th scope="row">Droplet already destroyed; volume and snapshot kept</th><td>No further Droplet charge</td><td>50 × $0.10 = $5</td><td>20 × $0.06 = $1.20</td><td>$6.20</td></tr>\n<tr><th scope="row">All three resources already deleted</th><td>No further charge</td><td>No further charge</td><td>No further charge</td><td>$0 for these resources going forward</td></tr>\n</tbody></table></div>\n<p>Data from DigitalOcean official documentation, checked 2026-11-13 02:10 UTC. Published rates: <a href="https://www.digitalocean.com/pricing/droplets">Basic Regular table, 1 GiB monthly cell</a>; <a href="https://docs.digitalocean.com/products/volumes/details/pricing/">Volume Pricing, pricing paragraph</a>; <a href="https://docs.digitalocean.com/products/snapshots/details/pricing/">Snapshots Pricing, pricing paragraph</a>. Every subtotal is our calculation, not an invoice.</p>\n<p>The second row models a later full month, not the month containing deletion. Already accrued charges still have to be paid. Deleting a Droplet is irreversible and is not the same as shutting down its operating system. Its associated resources are not deleted by default; choose what to retain and inspect those resources separately. Automatic backups have different retention rules and are outside this snapshot example.</p>\n<p>State evidence: <a href="https://docs.digitalocean.com/products/droplets/details/pricing/#bundled-cpu-droplet-billing">Bundled CPU Droplet Billing, paragraph 2</a>; <a href="https://docs.digitalocean.com/products/droplets/how-to/destroy/#destroy-a-droplet-from-the-control-panel">Destroy a Droplet from the Control Panel, associated-resource selection and final billing paragraph</a>; <a href="https://docs.digitalocean.com/products/volumes/details/pricing/">Volume Pricing, duration and attachment statements</a>.</p></section>\n<h2>A dated snapshot-copy change to include in next year\'s budget</h2>\n<section data-authored-calculation="snapshot-copies"><p>The official Snapshots Pricing note says that, beginning 1 January 2027, additional-region copies of a Droplet snapshot are charged at the original snapshot rate. This is a published future rule, not a prediction that all Droplet prices will rise.</p>\n<p>Scenario: one original 20 GB snapshot and one additional-region copy, each assumed to have 20 GB billable size, held for a complete billed month after that date. <strong>(20 + 20) GB × $0.06/GB-month = $2.40/month</strong>. The original alone is 20 × $0.06 = $1.20; the extra copy adds $1.20/month, or $14.40 over twelve complete months at the quoted rate. These assumed sizes are not a promise about actual incremental storage.</p>\n<p>Evidence: <a href="https://docs.digitalocean.com/products/snapshots/details/pricing/">Snapshots Pricing, first pricing paragraph and Note beginning “Beginning on 1 January 2027”</a>. Very small or short-lived snapshots can incur the documented minimum charge; this full-month example is not a proration calculator.</p></section>\n<h2>Who should use this price table?</h2>\n<p>Use it when a bundled Regular CPU shape fits your workload and you want to inspect a monthly compute cap plus separately billed resources. For a storage-heavy workload, price the volume and transfer before selecting the smallest Droplet. If you need managed application administration, guaranteed dedicated CPU performance, or a custom v5 shape, this table alone does not answer that purchase decision.</p>\n<h2>What was not obtained</h2>\n<ul><li>Guaranteed year-two or renewal tariff: <strong>Not obtained</strong>; only an explicitly unchanged-rate scenario is shown.</li><li>Account-specific credits and tax-inclusive checkout total: <strong>Not obtained</strong>; neither is subtracted from or added to the base table.</li><li>Automatic boot-disk overage unit price: <strong>Not obtained</strong>; the storage calculation uses a separately provisioned Standard volume.</li><li>Application-specific backup storage usage: <strong>Not obtained</strong>; it is not guessed from the boot-disk capacity.</li></ul>\n<h2>Sources and check date</h2><div id="sources">\n<p>Official pages checked <time datetime="2026-11-13T02:10:12+00:00">2026-11-13 02:10 UTC</time>. These are dated observations, not live checkout quotes. The three worked budgets above use labelled assumed quantities. No competitor supplies a price or billing rule on this page.</p>\n<ul><li><a href="https://www.digitalocean.com/pricing/droplets">Droplet pricing: Basic → Regular table</a></li><li><a href="https://docs.digitalocean.com/products/droplets/details/pricing/">Droplet Pricing: Bundled CPU Droplet Billing</a></li><li><a href="https://docs.digitalocean.com/platform/billing/bandwidth/">Bandwidth Billing: Droplets</a></li><li><a href="https://docs.digitalocean.com/products/volumes/details/pricing/">Volume Pricing</a></li><li><a href="https://docs.digitalocean.com/products/snapshots/details/pricing/">Snapshots Pricing</a></li><li><a href="https://docs.digitalocean.com/products/droplets/how-to/destroy/">Destroy a Droplet: associated-resource billing</a></li></ul>\n<p><a href="/">Home</a> · <a href="/compare/">Compare published plans</a> · <a href="/providers/digitalocean/">DigitalOcean provider</a></p></div>\n'
